using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class AudioEventCheck{
static BokumyakuGame g;static HashSet<string> seen;static double start;static bool bought,researched;static int frame;
public static object Run(){g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");g.SetAudioSettings(.6f,.4f,.5f,false);seen=new HashSet<string>();g.MenuClick();Sample();g.AbandonRun();g.SetWeapon(WeaponKind.Point);g.SetBuild(BuildPreset.Manual);g.SetSpeed(2);g.TryStartRun(42);g.SetAutoRepeat(false);Application.runInBackground=true;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();start=EditorApplication.timeSinceStartup;bought=researched=false;frame=Time.frameCount;EditorApplication.update+=Poll;return "Live event routing check, maximum 150 seconds";}
static void Sample(){foreach(var s in g.GetComponents<AudioSource>())if(s.clip!=null&&s.isPlaying&&s.volume>0&&!s.mute)seen.Add(s.clip.name);}
static void Poll(){if(g==null||!EditorApplication.isPlaying){EditorApplication.update-=Poll;return;}EditorApplication.QueuePlayerLoopUpdate();if(frame==Time.frameCount)return;frame=Time.frameCount;try{Sample();if(g.Run.State==RunStatus.Running){if(g.IsPaused)g.SetPaused(false);if(!bought&&g.Run.RunInk>=g.Run.UpgradeCost(UpgradeKind.Damage)){bought=g.BuyUpgrade(UpgradeKind.Damage);Sample();}}else if(seen.Contains("sfx_defeat")&&!researched){if(!g.SaveProgress())throw new Exception("Settle failed");g.SetPage(BokumyakuGame.GamePage.Research);researched=g.BuyMeta((MetaUpgrade)0);Sample();if(!researched)throw new Exception("Research failed");}if(seen.Count==8&&bought&&researched){Finish(null);return;}if(EditorApplication.timeSinceStartup-start>150)Finish("Event coverage deadline");}catch(Exception e){Finish(e.ToString());}}
static void Finish(string error){EditorApplication.update-=Poll;g.SetPaused(true);var expected=new[]{"sfx_click","sfx_purchase","sfx_attack_point","sfx_kill","sfx_core_hit","sfx_defeat","sfx_research_complete","bgm_sumi_no_ma_80s"};File.WriteAllText(Path.GetFullPath("../docs/evidence/audio-event-routing.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=error==null&&expected.All(seen.Contains),error,seen=seen.OrderBy(x=>x).ToArray(),missing=expected.Where(x=>!seen.Contains(x)).ToArray(),bought,researched,seconds=EditorApplication.timeSinceStartup-start,tick=g.Run.TickCount,wave=g.Run.Wave,method="Live 2x seed42 Manual run, one real upgrade, defeat settlement and research APIs; observe playing non-muted sources. Not subjective listening or physical touch."},Newtonsoft.Json.Formatting.Indented));}
}
